async Task ConsumeAsync(string body, CancellationToken ct)
{
    try
    {
        await HandleAsync(body, ct);
    }
    catch (OperationCanceledException) when (ct.IsCancellationRequested)
    {
        throw;
    }
    catch (TimeoutException ex)
    {
        Log(ex);
        throw; // host applies retry / DLQ policy
    }
    // ArgumentException and other bugs bubble untouched
}

static User ParseUser(string json)
{
    try
    {
        return JsonSerializer.Deserialize<User>(json)!;
    }
    catch (JsonException ex)
    {
        throw new InvalidOperationException("user JSON invalid", ex);
    }
}

static class Config
{
    static readonly string ApiKey = LoadKeyOrThrow();

    static string LoadKeyOrThrow()
    {
        var key = Environment.GetEnvironmentVariable("API_KEY");
        return key ?? throw new InvalidOperationException("API_KEY missing");
    }
}
